(() => {
  'use strict';
  const $ = (id) => document.getElementById(id);
  const fishCatalog = [
    {name:'Sunny Sardine',emoji:'🐟',value:8,xp:8,zone:0,rarity:'Common'},
    {name:'Puddle Perch',emoji:'🐠',value:12,xp:10,zone:0,rarity:'Common'},
    {name:'Ribbon Koi',emoji:'🐡',value:22,xp:18,zone:0,rarity:'Uncommon'},
    {name:'Moon Jelly',emoji:'🪼',value:35,xp:24,zone:0,rarity:'Rare'},
    {name:'Reed Hopper',emoji:'🐟',value:18,xp:14,zone:1,rarity:'Common'},
    {name:'Glassfin Trout',emoji:'🐠',value:35,xp:22,zone:1,rarity:'Uncommon'},
    {name:'Mossy Sturgeon',emoji:'🐡',value:55,xp:32,zone:1,rarity:'Rare'},
    {name:'Starry Mackerel',emoji:'🐟',value:45,xp:28,zone:2,rarity:'Uncommon'},
    {name:'Blue Comet',emoji:'🐠',value:70,xp:40,zone:2,rarity:'Rare'},
    {name:'Pearl-Eye',emoji:'🐡',value:95,xp:52,zone:2,rarity:'Epic'},
    {name:'Cloud Ray',emoji:'🪼',value:120,xp:65,zone:3,rarity:'Epic'},
    {name:'Aurora Fin',emoji:'🐠',value:180,xp:85,zone:3,rarity:'Legendary'}
  ];
  const zones = [
    {name:'Pebble Bay',short:'PEBBLE BAY',emoji:'🏖️',sub:'A good place to start',depth:'Shallows',unlock:0,boss:'The Old Tide',bossEmoji:'🐋',bossDesc:'A gentle giant guarding the bay.'},
    {name:'Willowmere',short:'WILLOWMERE',emoji:'🌿',sub:'Where the river bends',depth:'River bend',unlock:120,boss:'Reedjaw',bossEmoji:'🐊',bossDesc:'The ancient king of the reeds.'},
    {name:'Moonlit Reach',short:'MOONLIT REACH',emoji:'🌙',sub:'The stars touch the water',depth:'Open water',unlock:340,boss:'The Duskfin',bossEmoji:'🦈',bossDesc:'A shadow beneath the moon.'},
    {name:'Cloudbreak Cove',short:'CLOUDBREAK COVE',emoji:'☁️',sub:'Beyond the misty horizon',depth:'Deep blue',unlock:760,boss:'Skywhale',bossEmoji:'🐳',bossDesc:'A song older than the sea.'}
  ];
  const upgrades = [
    {key:'rod',name:'Bamboo rod',emoji:'🎣',desc:'Shorter waits between bites',base:30,effect:'cast speed'},
    {key:'reel',name:'Tangle-free reel',emoji:'🧵',desc:'More control while reeling',base:45,effect:'reel power'},
    {key:'lure',name:'Lucky lure',emoji:'✨',desc:'Better fish & bonus shells',base:65,effect:'luck'}
  ];
  const fresh = {coins:35,lifetime:35,xp:0,total:0,best:'—',day:1,zone:0,unlocked:[0],levels:{rod:0,reel:0,lure:0},caught:[],bosses:[],fishCount:{},lastSeen:Date.now()};
  let state;
  try { state={...fresh,...JSON.parse(localStorage.getItem('littleFinSave')||'{}')}; state.levels={...fresh.levels,...(state.levels||{})}; state.unlocked=state.unlocked||[0];state.bosses=state.bosses||[];state.fishCount=state.fishCount||{}; } catch { state={...fresh}; }
  let mode='idle', castTimer=null, biteTimer=null, meterTimer=null, meter=25, meterDirection=1, pull=0, activeBoss=null, toastTimer=null;
  const rand=(n)=>Math.floor(Math.random()*n);
  const save=()=>{state.lastSeen=Date.now();localStorage.setItem('littleFinSave',JSON.stringify(state));};
  const rankInfo=()=>{const levels=[100,220,380,590,850,1160,1520,1940,2420,2960];let level=1,remain=state.xp;while(level<=levels.length&&remain>=levels[level-1]){remain-=levels[level-1];level++;}const cap=levels[Math.min(level-1,levels.length-1)]||3400;const names=['New Angler','River Regular','Tide Tracker','Reef Roamer','Deep Diver','Current Keeper','Wave Walker','Sea Sage','Ocean Elder','Legend of the Blue','Master Angler'];const icons=['🪶','🌱','🐚','🪸','🫧','🧭','🌊','🔱','🌌','✨','👑'];return{level,xp:remain,cap,name:names[Math.min(level-1,names.length-1)],icon:icons[Math.min(level-1,icons.length-1)],next:names[Math.min(level,names.length-1)]};};
  const bossUnlocked=()=>rankInfo().level>=3;
  function toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100);}
  function render(){
    const r=rankInfo();$('coins').textContent=Math.floor(state.coins).toLocaleString();$('lifetime-coins').textContent=Math.floor(state.lifetime).toLocaleString();$('day-count').textContent=String(state.day).padStart(2,'0');$('total-caught').textContent=state.total;$('best-catch').textContent=state.best;
    $('rank-icon').textContent=r.icon;$('rank-name').textContent=r.name;$('rank-level').textContent='LVL '+r.level;$('xp-current').textContent=r.xp;$('xp-needed').textContent=r.cap;$('xp-fill').style.width=Math.min(100,r.xp/r.cap*100)+'%';$('rank-next').textContent=r.level>=11?'Max rank reached':'Next: '+r.next;$('xp-next-label').textContent=r.level<3?`${Math.max(0,2-r.level)} more rank${r.level===1?'s':''} until a boss encounter`:'A legendary fish awaits…';
    const zone=zones[state.zone];$('zone-name').textContent=zone.name;$('zone-emoji').textContent=zone.emoji;$('zone-short').textContent=zone.short;$('zone-subtitle').textContent=zone.sub;$('depth-label').textContent=zone.depth;
    $('species-count').innerHTML=`${Object.keys(state.fishCount).length} <small>/ 12</small>`;$('nav-journal-count').textContent=Object.keys(state.fishCount).length;$('nav-journal-count').classList.toggle('show',Object.keys(state.fishCount).length>0);
    $('kit-level').textContent=Object.values(state.levels).reduce((a,b)=>a+b,0)===0?'STARTER KIT':'KIT LVL '+(Object.values(state.levels).reduce((a,b)=>a+b,0)+1);
    renderUpgrades();renderJournal();renderBossTeaser();save();
  }
  function renderUpgrades(){const box=$('upgrade-list');box.innerHTML='';upgrades.forEach(u=>{const lv=state.levels[u.key],cost=Math.floor(u.base*Math.pow(1.72,lv));const row=document.createElement('div');row.className='upgrade-row';row.innerHTML=`<div class="upgrade-art">${u.emoji}</div><div class="upgrade-info"><div class="upgrade-name">${u.name} <span class="upgrade-level">LV ${lv}</span></div><div class="upgrade-desc">${u.desc}</div></div><button class="upgrade-buy ${lv>=8?'maxed':''}" ${lv>=8||state.coins<cost?'disabled':''}>${lv>=8?'MAX':'◉ '+cost}<span>${lv>=8?'':u.effect}</span></button>`;row.querySelector('button').onclick=()=>buyUpgrade(u);box.appendChild(row);});}
  function renderJournal(){const box=$('journal-row');box.innerHTML='';fishCatalog.slice(0,5).forEach(f=>{const discovered=state.fishCount[f.name]>0;const item=document.createElement('div');item.className='journal-fish'+(discovered?'':' locked');item.innerHTML=`<span class="fish-emoji">${discovered?f.emoji:'？'}</span><small>${discovered?f.name.split(' ')[0]:'Unknown'}</small>`;box.appendChild(item);});}
  function renderBossTeaser(){const z=zones[state.zone],defeated=state.bosses.includes(state.zone),unlocked=bossUnlocked();$('boss-teaser-title').textContent=defeated?'Guardian befriended':z.boss;$('boss-teaser-desc').textContent=defeated?'A new friend in your fishing tales.':unlocked?'The guardian is ready to meet you.':`Reach rank 3 to challenge ${z.name==='Pebble Bay'?'the bay':'this water'}'s guardian.`;$('boss-lock').textContent=defeated?'✓':unlocked?'⚔':'🔒';$('boss-lock').style.color=unlocked?'#d09659':'';}
  function buyUpgrade(u){const lv=state.levels[u.key],cost=Math.floor(u.base*Math.pow(1.72,lv));if(lv>=8||state.coins<cost)return;state.coins-=cost;state.levels[u.key]++;toast(`${u.name} upgraded to level ${lv+1}!`);render();}
  function setStatus(text){$('status-copy').textContent=text;}
  function cast(){if(mode==='boss-ready'){startBossCast();return;}if(mode==='bite'){reel();return;}if(mode!=='idle')return;mode='casting';$('cast-button').disabled=true;$('cast-label').textContent='Waiting…';$('action-title').textContent='Line in the water';$('action-subtitle').textContent='A little patience...';$('bobber').style.opacity='1';$('fishing-line').style.height='85px';$('scene-fish').classList.remove('show');$('action-icon').textContent='🌊';setStatus('Waiting for a nibble…');const delay=Math.max(1100,3900-state.levels.rod*480);castTimer=setTimeout(startBite,delay);}
  function startBite(){if(mode!=='casting')return;mode='bite';meter=28+rand(25);meterDirection=Math.random()<.5?1:-1;pull=0;$('bite-meter').classList.add('show');$('cast-label').textContent='Reel!';$('cast-button').disabled=false;$('cast-button').classList.add('reeling');$('action-title').textContent='Something took the bait!';$('action-subtitle').textContent='Tap REEL to bring it in!';$('action-icon').textContent='🐟';$('scene-fish').textContent='🐟';$('scene-fish').classList.add('show');setStatus('A bite! Reel it in!');meterTimer=setInterval(()=>{meter+=meterDirection*(2+Math.random()*1.5);if(meter>92){meter=92;meterDirection=-1;}if(meter<8){meter=8;meterDirection=1;}$('meter-fill').style.width=meter+'%';$('meter-fill').style.background=meter>=37&&meter<=61?'#77c7a2':meter<20||meter>82?'#ed9a76':'#dfc56d';},110);biteTimer=setTimeout(()=>{if(mode==='bite'){clearInterval(meterTimer);mode='idle';resetCast();toast('The fish slipped away. Try again!');}},12000);}
  function reel(){if(mode!=='bite')return;pull+=1+state.levels.reel*.32;const inSweet=meter>=37&&meter<=61;if(inSweet)pull+=1.3;meter=Math.max(8,Math.min(92,meter+(meter<50?8:-8)));$('meter-fill').style.width=meter+'%';if(pull>= (activeBoss?activeBoss.target:4.4)){clearInterval(meterTimer);clearTimeout(biteTimer);if(activeBoss)bossHit(inSweet);else catchFish(inSweet);}}
  function chooseFish(){const pool=fishCatalog.filter(f=>f.zone===state.zone);const luck=state.levels.lure;let weights=pool.map((f,i)=>Math.max(1,9-i*2+luck*(f.rarity==='Rare'||f.rarity==='Epic'||f.rarity==='Legendary'?2:0)));let n=Math.random()*weights.reduce((a,b)=>a+b,0);for(let i=0;i<pool.length;i++){n-=weights[i];if(n<=0)return pool[i];}return pool[0];}
  function catchFish(perfect){const f=chooseFish(),bonus=perfect?1.2:1,earned=Math.round(f.value*bonus*(1+state.levels.lure*.12));state.coins+=earned;state.lifetime+=earned;state.xp+=f.xp;state.total++;state.fishCount[f.name]=(state.fishCount[f.name]||0)+1;if(f.value>(fishCatalog.find(a=>a.name===state.best)?.value||0))state.best=f.name;state.day=Math.max(state.day,Math.floor(state.total/7)+1);$('scene-fish').textContent=f.emoji;$('action-icon').textContent=f.emoji;$('action-title').textContent=`A ${f.name}!`;$('action-subtitle').textContent=`+${earned} shells  ·  +${f.xp} XP${perfect?'  ·  Nice timing!':''}`;setStatus(perfect?'Perfect catch!':'Fish on board!');$('cast-button').disabled=true;$('cast-label').textContent='Nice catch!';$('bite-meter').classList.remove('show');$('bobber').style.opacity='0';$('scene-fish').classList.add('show');mode='caught';const before=rankInfo().level;render();if(rankInfo().level>before)toast(`Rank up! You are now ${rankInfo().name}!`);setTimeout(()=>{if(mode==='caught'){mode='idle';resetCast();}},1550);}
  function resetCast(){mode=activeBoss?'boss-ready':'idle';$('cast-button').disabled=false;$('cast-button').classList.remove('reeling');$('cast-label').textContent=activeBoss?'Face the guardian':'Cast line';$('button-key').textContent='SPACE';$('action-title').textContent=activeBoss?'A guardian awaits':'Ready when you are';$('action-subtitle').textContent=activeBoss?'Cast into the deep to begin the challenge.':'Cast your line and see what bites.';$('action-icon').textContent=activeBoss?'⚔':'🎣';$('bite-meter').classList.remove('show');$('bobber').style.opacity='0';$('fishing-line').style.height='70px';if(!activeBoss){$('scene-fish').classList.remove('show');setStatus('The water is calm...');}}
  const bossHP={};

