function startBossCast(){if(!activeBoss||mode!=='boss-ready')return;mode='casting';$('cast-button').disabled=true;$('cast-label').textContent='Waiting…';$('action-title').textContent='The water begins to stir';$('action-subtitle').textContent='Something enormous is rising...';$('action-icon').textContent='🌊';$('bobber').style.opacity='1';$('fishing-line').style.height='90px';setStatus('A guardian is approaching…');setTimeout(()=>{if(mode==='casting')startBite();},1250);}
function challengeBoss(){if(!bossUnlocked()){toast('Reach rank 3 to challenge the guardian.');return;}if(state.bosses.includes(state.zone)){toast('You have already befriended this guardian!');return;}const z=zones[state.zone];activeBoss={hp:4,max:4,target:5.5,name:z.boss,emoji:z.bossEmoji};mode='boss-ready';$('boss-scene').classList.add('show');$('boss-scene').setAttribute('aria-hidden','false');$('boss-sprite').textContent=z.bossEmoji;$('boss-scene-name').textContent=z.boss.toUpperCase();$('scene-card').classList.add('boss-active');let hud=$('boss-hud');if(!hud){hud=document.createElement('div');hud.id='boss-hud';hud.className='boss-hud';hud.innerHTML='<div class="boss-hud-top"><span>GUARDIAN</span><span id="boss-hp-text">4 / 4</span></div><div class="boss-hp-track"><div class="boss-hp-fill" id="boss-hp-fill"></div></div>';$('water').appendChild(hud);}hud.style.display='block';$('cast-label').textContent='Face the guardian';$('action-title').textContent='A guardian awaits';$('action-subtitle').textContent='Cast into the deep to begin the challenge.';$('action-icon').textContent='⚔';$('cast-button').disabled=false;setStatus('The guardian is watching…');$('modal-backdrop').hidden=true;toast(`${z.boss} has appeared!`);}
function bossHit(perfect){if(!activeBoss)return;activeBoss.hp-=perfect?1.35:1;const hp=Math.max(0,activeBoss.hp);$('boss-hp-fill').style.width=(hp/activeBoss.max*100)+'%';$('boss-hp-text').textContent=`${Math.ceil(hp)} / ${activeBoss.max}`;$('scene-fish').textContent=activeBoss.emoji;$('scene-fish').classList.add('show');if(hp<=0){const z=state.zone,reward=140+z*110;state.coins+=reward;state.lifetime+=reward;state.xp+=100+z*60;state.bosses.push(z);if(z<zones.length-1&&!state.unlocked.includes(z+1)){state.unlocked.push(z+1);toast(`${activeBoss.name} is defeated! New water unlocked!`);}else toast(`${activeBoss.name} is defeated! +${reward} shells`);activeBoss=null;mode='idle';$('boss-scene').classList.remove('show');$('scene-card').classList.remove('boss-active');$('boss-hud').style.display='none';$('scene-fish').classList.remove('show');render();resetCast();return;}mode='boss-ready';$('cast-button').disabled=false;$('cast-button').classList.remove('reeling');$('cast-label').textContent='Cast again';$('action-title').textContent=`A solid hit! ${Math.ceil(hp)} strength left`;$('action-subtitle').textContent=perfect?'Great timing! Cast again to wear it down.':'The guardian is shaken. Keep going!';$('action-icon').textContent='💥';$('bite-meter').classList.remove('show');$('bobber').style.opacity='0';setStatus('Guardian weakened!');}
function showModal(title,eyebrow,body){$('modal-content').innerHTML=`<span class="eyebrow">${eyebrow}</span><h2>${title}</h2>${body}`;$('modal-backdrop').hidden=false;}
function showZones(){let html='<div class="modal-list">';zones.forEach((z,i)=>{const unlocked=state.unlocked.includes(i),selected=i===state.zone;html+=`<div class="modal-item"><span class="item-emoji">${z.emoji}</span><div style="flex:1"><b>${z.name}${selected?' · Current':''}</b><small>${unlocked?z.sub:`Unlock for ${z.unlock} shells`}</small></div><button class="upgrade-buy" data-zone="${i}" ${!unlocked&&state.coins<z.unlock?'disabled':''}>${selected?'Here':unlocked?'Visit':'◉ '+z.unlock}</button></div>`;});html+='</div>';$('modal-content').innerHTML='<span class="eyebrow">FOLLOW THE CURRENT</span><h2>Choose your waters</h2><p>Each spot has its own fish, treasures, and guardian.</p>'+html;$('modal-backdrop').hidden=false;$('modal-content').querySelectorAll('[data-zone]').forEach(btn=>btn.onclick=()=>{const i=+btn.dataset.zone,z=zones[i];if(state.unlocked.includes(i)){state.zone=i;render();$('modal-backdrop').hidden=true;resetCast();}else if(state.coins>=z.unlock){state.coins-=z.unlock;state.unlocked.push(i);state.zone=i;render();$('modal-backdrop').hidden=true;resetCast();toast(`${z.name} unlocked!`);}});}
function showJournal(){const items=fishCatalog.map(f=>{const n=state.fishCount[f.name]||0;return`<div class="modal-item"><span class="item-emoji">${n?f.emoji:'❔'}</span><div style="flex:1"><b>${n?f.name:'Unknown species'}</b><small>${n?`${f.rarity} · caught ${n} time${n===1?'':'s'} · ${f.zone===state.zone?'Here':zones[f.zone].name}`:'Cast your line to discover this fish'}</small></div>${n?`<b style="color:#bd9857;font-size:10px">${f.value}◉</b>`:''}</div>`;}).join('');showModal('Field journal','A RECORD OF YOUR CATCHES',`<p>${Object.keys(state.fishCount).length} of 12 species discovered. There are always more fish in another water.</p><div class="modal-list">${items}</div>`);}
function showHelp(){showModal('A little guide','WELCOME TO THE WATER',`<p>Take it slow. There’s no rush out here.</p><div class="modal-list"><div class="modal-item"><span class="item-emoji">🎣</span><div><b>Cast your line</b><small>Wait for a bite, then tap Reel (or press Space) to bring it in.</small></div></div><div class="modal-item"><span class="item-emoji">🟩</span><div><b>Watch the green zone</b><small>Reel when the moving marker is in the green for a better catch.</small></div></div><div class="modal-item"><span class="item-emoji">🧰</span><div><b>Upgrade your kit</b><small>Better rods, reels, and lures make fishing faster and luckier.</small></div></div><div class="modal-item"><span class="item-emoji">🐋</span><div><b>Meet the guardians</b><small>Reach rank 3, then challenge each water’s legendary guardian.</small></div></div></div><div class="modal-actions"><button class="modal-action" id="help-ok">Let’s fish</button></div>`);$('help-ok').onclick=()=>$('modal-backdrop').hidden=true;}
function resetCast(){mode=activeBoss?'boss-ready':'idle';$('cast-button').disabled=false;$('cast-button').classList.remove('reeling');$('cast-label').textContent=activeBoss?'Cast again':'Cast line';$('action-title').textContent=activeBoss?'A guardian awaits':'Ready when you are';$('action-subtitle').textContent=activeBoss?'Cast into the deep to begin the challenge.':'Cast your line and see what bites.';$('action-icon').textContent=activeBoss?'⚔':'🎣';$('bite-meter').classList.remove('show');$('bobber').style.opacity='0';$('fishing-line').style.height='70px';if(!activeBoss){$('scene-fish').classList.remove('show');setStatus('The water is calm...');}}

