49:   function renderBossTeaser(){const z=zones[state.zone],defeated=state.bosses.includes(state.zone),unlocked=bossUnlocked();$('boss-teaser-title').textContent=defeated?'Guardian befriended':z.boss;$('boss-teaser-desc').textContent=defeated?'A new friend in your fishing tales.':unlocked?'The guardian is ready to meet you.':`Reach rank 3 to challenge ${z.name==='Pebble Bay'?'the bay':'this water'}'s guardian.`;$('boss-lock').textContent=defeated?'✓':unlocked?'⚔':'🔒';$('boss-lock').style.color=unlocked?'#d09659':'';}
50:   function buyUpgrade(u){const lv=state.levels[u.key],cost=Math.floor(u.base*Math.pow(1.72,lv));if(lv>=8||state.coins<cost)return;state.coins-=cost;state.levels[u.key]++;toast(`${u.name} upgraded to level ${lv+1}!`);render();}
51:   function setStatus(text){$('status-copy').textContent=text;}
52:   function cast(){if(mode==='boss-ready'){startBossCast();return;}if(mode==='bite'){reel();return;}if(mode!=='idle')return;mode='casting';$('cast-button').disabled=true;$('cast-label').textContent='Waiting…';$('action-title').textContent='Line in the water';$('action-subtitle').textContent='A little patience...';$('bobber').style.opacity='1';$('fishing-line').style.height='85px';$('scene-fish').classList.remove('show');$('action-icon').textContent='🌊';setStatus('Waiting for a nibble…');const delay=Math.max(1100,3900-state.levels.rod*480);castTimer=setTimeout(startBite,delay);}
53:   function startBite(){if(mode!=='casting')return;mode='bite';meter=28+rand(25);meterDirection=Math.random()<.5?1:-1;pull=0;$('bite-meter').classList.add('show');$('cast-label').textContent='Reel!';$('cast-button').disabled=false;$('cast-button').classList.add('reeling');$('action-title').textContent=activeBoss?`${activeBoss.name} took the bait!`:'Something took the bait!';$('action-subtitle').textContent='Tap REEL to bring it in!';$('action-icon').textContent=activeBoss?'⚔':'🐟';$('scene-fish').textContent=activeBoss?activeBoss.emoji:'🐟';$('scene-fish').classList.add('show');setStatus(activeBoss?'The guardian surges! Reel it in!':'A bite! Reel it in!');meterTimer=setInterval(()=>{meter+=meterDirection*(2+Math.random()*1.5);if(meter>92){meter=92;meterDirection=-1;}if(meter<8){meter=8;meterDirection=1;}$('meter-fill').style.width=meter+'%';$('meter-fill').style.background=meter>=37&&meter<=61?'#77c7a2':meter<20||meter>82?'#ed9a76':'#dfc56d';},110);biteTimer=setTimeout(()=>{if(mode==='bite'){clearInterval(meterTimer);mode='idle';resetCast();toast('The fish slipped away. Try again!');}},12000);}
54:   function reel(){if(mode!=='bite')return;pull+=1+state.levels.reel*.32;const inSweet=meter>=37&&meter<=61;if(inSweet)pull+=1.3;meter=Math.max(8,Math.min(92,meter+(meter<50?8:-8)));$('meter-fill').style.width=meter+'%';if(pull>= (activeBoss?activeBoss.target:4.4)){clearInterval(meterTimer);clearTimeout(biteTimer);if(activeBoss)bossHit(inSweet);else catchFish(inSweet);}}
55:   function chooseFish(){const pool=fishCatalog.filter(f=>f.zone===state.zone);const luck=state.levels.lure;let weights=pool.map((f,i)=>Math.max(1,9-i*2+luck*(f.rarity==='Rare'||f.rarity==='Epic'||f.rarity==='Legendary'?2:0)));let n=Math.random()*weights.reduce((a,b)=>a+b,0);for(let i=0;i<pool.length;i++){n-=weights[i];if(n<=0)return pool[i];}return pool[0];}
56:   function catchFish(perfect){const f=chooseFish(),bonus=perfect?1.2:1,earned=Math.round(f.value*bonus*(1+state.levels.lure*.12));state.coins+=earned;state.lifetime+=earned;state.xp+=f.xp;state.total++;state.fishCount[f.name]=(state.fishCount[f.name]||0)+1;if(f.value>(fishCatalog.find(a=>a.name===state.best)?.value||0))state.best=f.name;state.day=Math.max(state.day,Math.floor(state.total/7)+1);$('scene-fish').textContent=f.emoji;$('action-icon').textContent=f.emoji;$('action-title').textContent=`A ${f.name}!`;$('action-subtitle').textContent=`+${earned} shells  ·  +${f.xp} XP${perfect?'  ·  Nice timing!':''}`;setStatus(perfect?'Perfect catch!':'Fish on board!');$('cast-button').disabled=true;$('cast-label').textContent='Nice catch!';$('bite-meter').classList.remove('show');$('bobber').style.opacity='0';$('scene-fish').classList.add('show');mode='caught';const before=rankInfo().level;render();if(rankInfo().level>before)toast(`Rank up! You are now ${rankInfo().name}!`);setTimeout(()=>{if(mode==='caught'){mode='idle';resetCast();}},1550);}
57:   function startBossCast(){if(!activeBoss||mode!=='boss-ready')return;mode='casting';$('cast-button').disabled=true;$('cast-label').textContent='Waiting…';$('action-title').textContent='The water begins to stir';$('action-subtitle').textContent='Something enormous is rising...';$('action-icon').textContent='🌊';$('bobber').style.opacity='1';$('fishing-line').style.height='90px';setStatus('A guardian is approaching…');setTimeout(()=>{if(mode==='casting')startBite();},1250);}
