60:   function showModal(title,eyebrow,body){$('modal-content').innerHTML=`<span class="eyebrow">${eyebrow}</span><h2>${title}</h2>${body}`;$('modal-backdrop').hidden=false;}
61:   function showZones(){let html='<div class="modal-list">';zones.forEach((z,i)=>{const unlocked=state.unlocked.includes(i),selected=i===state.zone;html+=`<div class="modal-item"><span class="item-emoji">${z.emoji}</span><div style="flex:1"><b>${z.name}${selected?' · Current':''}</b><small>${unlocked?z.sub:`Unlock for ${z.unlock} shells`}</small></div><button class="upgrade-buy" data-zone="${i}" ${!unlocked&&state.coins<z.unlock?'disabled':''}>${selected?'Here':unlocked?'Visit':'◉ '+z.unlock}</button></div>`;});html+='</div>';$('modal-content').innerHTML='<span class="eyebrow">FOLLOW THE CURRENT</span><h2>Choose your waters</h2><p>Each spot has its own fish, treasures, and guardian.</p>'+html;$('modal-backdrop').hidden=false;$('modal-content').querySelectorAll('[data-zone]').forEach(btn=>btn.onclick=()=>{const i=+btn.dataset.zone,z=zones[i];if(state.unlocked.includes(i)){state.zone=i;render();$('modal-backdrop').hidden=true;resetCast();}else if(state.coins>=z.unlock){state.coins-=z.unlock;state.unlocked.push(i);state.zone=i;render();$('modal-backdrop').hidden=true;resetCast();toast(`${z.name} unlocked!`);}});}
62:   function showJournal(){const items=fishCatalog.map(f=>{const n=state.fishCount[f.name]||0;return`<div class="modal-item"><span class="item-emoji">${n?f.emoji:'❔'}</span><div style="flex:1"><b>${n?f.name:'Unknown species'}</b><small>${n?`${f.rarity} · caught ${n} time${n===1?'':'s'} · ${f.zone===state.zone?'Here':zones[f.zone].name}`:'Cast your line to discover this fish'}</small></div>${n?`<b style="color:#bd9857;font-size:10px">${f.value}◉</b>`:''}</div>`;}).join('');showModal('Field journal','A RECORD OF YOUR CATCHES',`<p>${Object.keys(state.fishCount).length} of 12 species discovered. There are always more fish in another water.</p><div class="modal-list">${items}</div>`);}
63:   function showHelp(){showModal('A little guide','WELCOME TO THE WATER',`<p>Take it slow. There’s no rush out here.</p><div class="modal-list"><div class="modal-item"><span class="item-emoji">🎣</span><div><b>Cast your line</b><small>Wait for a bite, then tap Reel (or press Space) to bring it in.</small></div></div><div class="modal-item"><span class="item-emoji">🟩</span><div><b>Watch the green zone</b><small>Reel when the moving marker is in the green for a better catch.</small></div></div><div class="modal-item"><span class="item-emoji">🧰</span><div><b>Upgrade your kit</b><small>Better rods, reels, and lures make fishing faster and luckier.</small></div></div><div class="modal-item"><span class="item-emoji">🐋</span><div><b>Meet the guardians</b><small>Reach rank 3, then challenge each water’s legendary guardian.</small></div></div></div><div class="modal-actions"><button class="modal-action" id="help-ok">Let’s fish</button></div>`);$('help-ok').onclick=()=>$('modal-backdrop').hidden=true;}
64:   function resetCast(){mode=activeBoss?'boss-ready':'idle';$('cast-button').disabled=false;$('cast-button').classList.remove('reeling');$('cast-label').textContent=activeBoss?'Cast again':'Cast line';$('action-title').textContent=activeBoss?'A guardian awaits':'Ready when you are';$('action-subtitle').textContent=activeBoss?'Cast into the deep to begin the challenge.':'Cast your line and see what bites.';$('action-icon').textContent=activeBoss?'⚔':'🎣';$('bite-meter').classList.remove('show');$('bobber').style.opacity='0';$('fishing-line').style.height='70px';if(!activeBoss){$('scene-fish').classList.remove('show');setStatus('The water is calm...');}}
