66:     const away=Math.min(8*60*60,Math.max(0,(Date.now()-(state.lastSeen||Date.now()))/1000));const offline=Math.floor(away*state.levels.net*.06);if(offline>0){state.coins+=offline;state.lifetime+=offline;setTimeout(()=>toast(`Your drift net brought home ${offline} shells.`),650);}
67:     render();$('cast-button').addEventListener('click',cast);$('zone-switch').addEventListener('click',showZones);$('journal-button').addEventListener('click',showJournal);$('help-button').addEventListener('click',showHelp);$('boss-teaser').addEventListener('click',()=>bossUnlocked()&&!state.bosses.includes(state.zone)?challengeBoss():(!bossUnlocked()?toast('Reach rank 3 to challenge the guardian.'):toast('You have already befriended this guardian!')));$('modal-close').addEventListener('click',()=>$('modal-backdrop').hidden=true);$('modal-backdrop').addEventListener('click',e=>{if(e.target===$('modal-backdrop'))$('modal-backdrop').hidden=true;});$('sound-toggle').addEventListener('click',e=>{const btn=e.currentTarget,off=btn.dataset.off==='true';btn.dataset.off=String(!off);btn.style.opacity=off?'1':'.45';toast(off?'Sound on':'Sound off');});
68:     document.addEventListener('keydown',e=>{if(e.code==='Space'&&!e.repeat&&!e.target.closest('button')){e.preventDefault();cast();}if(e.key==='Escape')$('modal-backdrop').hidden=true;});
69:     document.querySelectorAll('.nav-item').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.nav-item').forEach(n=>n.classList.remove('active'));btn.classList.add('active');if(btn.dataset.tab==='waters')showZones();else if(btn.dataset.tab==='journal')showJournal();else if(btn.dataset.tab==='upgrades')document.querySelector('.upgrades-panel').scrollIntoView({behavior:'smooth',block:'center'});else window.scrollTo({top:0,behavior:'smooth'});}));
