@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Nunito:wght@700;800;900&display=swap');

:root{color-scheme:light;--ink:#203b3d;--muted:#839795;--teal:#438b80;--deep:#173b43;--line:#e6eeea;--paper:#fff;--cream:#f7f8f2;--gold:#d5a85c;--shadow:0 12px 32px rgba(31,67,62,.07)}
*{box-sizing:border-box}
html{min-width:320px;background:#f4f7f3;scroll-behavior:smooth}
body{margin:0;color:var(--ink);background:radial-gradient(ellipse at 42% -20%,#fff 0,#f6f8f4 52%,#eff4ef 100%);font:14px/1.45 'DM Sans',sans-serif;min-height:100vh}
button,a{-webkit-tap-highlight-color:transparent}
button{font:inherit}
.app-shell{width:min(1120px,100%);margin:0 auto;padding:0 30px}
.topbar{height:78px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(217,229,222,.78)}
.brand{display:flex;align-items:center;gap:10px;color:#234447;text-decoration:none;font:900 25px/1 'Nunito',sans-serif;letter-spacing:-1.3px}.brand-dot{color:#e2a35d}
.brand-icon{width:36px;height:36px;border-radius:12px;display:grid;place-items:center;background:#d9eee5;color:#398578;font-size:23px;transform:rotate(-8deg)}
.season{display:flex;align-items:center;gap:9px;color:#869a94;font-size:10px;font-weight:800;letter-spacing:1.35px}.season-icon{color:#e5ae55;font-size:18px}.season b{color:#345653;font-size:12px}.season-divider{height:17px;width:1px;background:#dbe5df;margin:0 4px}.weather{font-size:11px;font-weight:600;letter-spacing:0;color:#82948e}
.top-actions{display:flex;gap:9px}.icon-button{width:36px;height:36px;border-radius:12px;border:1px solid #e3ebe5;background:rgba(255,255,255,.82);color:#588079;font-size:16px;font-weight:800;cursor:pointer;transition:.18s}.icon-button:hover{border-color:#bcd8cd;background:#edf7f1;transform:translateY(-1px)}
.game-layout{display:grid;grid-template-columns:minmax(0,1.56fr) minmax(300px,.9fr);gap:24px;padding:24px 0 25px;align-items:start}.main-column,.side-column{min-width:0}.main-column{display:flex;flex-direction:column;gap:15px}.side-column{display:flex;flex-direction:column;gap:14px}
.scene-card{height:440px;position:relative;overflow:hidden;border-radius:21px;background:#d8eee6;box-shadow:var(--shadow);isolation:isolate}.scene-sky{height:174px;position:absolute;inset:0 0 auto;background:linear-gradient(180deg,#c8e9e5 0%,#dff0e7 77%,#d2e8de 100%);overflow:hidden}.sun{position:absolute;width:58px;height:58px;right:13%;top:38px;border-radius:50%;background:#ffe5a7;box-shadow:0 0 0 12px rgba(255,242,196,.32),0 0 38px #fff3c6}.cloud{position:absolute;width:82px;height:21px;border-radius:30px;background:rgba(255,255,255,.62);filter:blur(.2px)}.cloud:before,.cloud:after{content:'';position:absolute;background:inherit;border-radius:50%}.cloud:before{width:33px;height:30px;left:15px;top:-12px}.cloud:after{width:25px;height:24px;left:39px;top:-6px}.cloud-one{left:16%;top:55px;transform:scale(.8)}.cloud-two{right:33%;top:91px;transform:scale(.55);opacity:.7}.distant-island{position:absolute;bottom:-1px;width:36%;height:53px;background:#8eb4a3;clip-path:polygon(0 100%,14% 55%,23% 60%,35% 18%,47% 50%,58% 34%,72% 75%,100% 100%)}.island-one{left:-3%;opacity:.8}.island-two{right:-2%;width:43%;height:38px;background:#aac8b2;transform:scaleX(-1)}
.scene-title{position:absolute;z-index:3;top:24px;left:25px;display:flex;align-items:center;gap:12px}.location-pin{display:grid;place-items:center;width:39px;height:39px;border:1px solid rgba(255,255,255,.8);border-radius:13px;background:rgba(255,255,255,.64);color:#4d8b7b;font-size:22px;box-shadow:0 4px 12px #49796a13}.eyebrow{display:block;color:#89a09a;font-size:8px;font-weight:800;letter-spacing:1.45px}.scene-title h1{margin:2px 0 0;color:#24484a;font:900 23px/1.1 'Nunito',sans-serif;letter-spacing:-.4px}.zone-switch{margin-left:7px;padding:8px 11px;border:1px solid rgba(255,255,255,.75);border-radius:10px;background:rgba(255,255,255,.55);color:#51776f;font-size:10px;font-weight:700;cursor:pointer;white-space:nowrap}.zone-switch:hover{background:#fff}.zone-switch span{margin-left:4px;color:#d09a56}
.water{position:absolute;z-index:1;top:154px;left:0;right:0;bottom:0;overflow:hidden;background:linear-gradient(180deg,#75bdb3 0%,#57a6a4 45%,#448e96 100%);transition:background .3s}.water:before{content:'';position:absolute;inset:0;background:linear-gradient(110deg,rgba(228,248,225,.2),transparent 35%,rgba(18,92,111,.1) 78%)}.water-shimmer{position:absolute;height:2px;border-radius:100%;background:rgba(222,255,225,.68);box-shadow:0 0 10px rgba(220,255,228,.55);animation:shimmer 4s ease-in-out infinite}.shimmer-a{top:26%;left:10%;width:100px}.shimmer-b{top:48%;left:54%;width:145px;animation-delay:-1.3s}.shimmer-c{top:72%;left:25%;width:65px;animation-delay:-2.3s}@keyframes shimmer{0%,100%{opacity:.25;transform:translateX(-8px)}50%{opacity:.8;transform:translateX(12px)}}
